import sys
sys.setrecursionlimit(10000)

# ---------- Dinic max flow ----------
class Dinic:
    def __init__(self, N):
        self.N = N
        self.graph = [[] for _ in range(N)]

    def add_edge(self, fr, to, cap):
        forward = [to, cap, None]
        backward = [fr, 0, forward]
        forward[2] = backward
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs(self, s, t, level):
        from collections import deque
        q = deque([s])
        level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev in self.graph[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        return level[t] >= 0

    def dfs(self, v, t, f, level, it):
        if v == t:
            return f
        for i in range(it[v], len(self.graph[v])):
            it[v] = i
            to, cap, rev = self.graph[v][i]
            if cap > 0 and level[v] + 1 == level[to]:
                ret = self.dfs(to, t, min(f, cap), level, it)
                if ret > 0:
                    # decrease forward, increase backward
                    self.graph[v][i][1] -= ret
                    rev[1] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        level = [0] * self.N
        while True:
            level = [-1] * self.N
            if not self.bfs(s, t, level):
                break
            it = [0] * self.N
            while True:
                f = self.dfs(s, t, INF, level, it)
                if f == 0:
                    break
                flow += f
        return flow


# ---------- Tarjan SCC (iterative) ----------
def tarjan_scc(adj, n):
    """
    adj: list of sets or lists, vertices 0..n-1
    returns list comp where comp[v] is component id (0..K-1)
    """
    index = 0
    indices = [-1] * n
    lowlink = [0] * n
    onstack = [False] * n
    stack = []
    comp = [-1] * n
    comp_cnt = 0

    def strongconnect(v):
        nonlocal index, comp_cnt
        indices[v] = lowlink[v] = index
        index += 1
        stack.append(v)
        onstack[v] = True
        for w in adj[v]:
            if indices[w] == -1:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif onstack[w]:
                lowlink[v] = min(lowlink[v], indices[w])
        if lowlink[v] == indices[v]:
            # pop until v
            while True:
                w = stack.pop()
                onstack[w] = False
                comp[w] = comp_cnt
                if w == v:
                    break
            comp_cnt += 1

    for v in range(n):
        if indices[v] == -1:
            strongconnect(v)
    return comp, comp_cnt


# ---------- Main solver ----------
def _solve(n, product_names):
    # Build adjacency matrix of letter pairs (26 letters)
    V = 26
    edge_cnt = [[0]*V for _ in range(V)]
    for name in product_names:
        u = ord(name[0]) - ord('A')
        v = ord(name[1]) - ord('A')
        edge_cnt[u][v] += 1

    # Build graph for SCC (existence of at least one edge)
    adj = [set() for _ in range(V)]
    for i in range(V):
        for j in range(V):
            if edge_cnt[i][j] > 0:
                adj[i].add(j)

    comp, K = tarjan_scc(adj, V)

    # Build condensation multiplicity matrix
    m = [[0]*K for _ in range(K)]
    for i in range(V):
        for j in range(V):
            if edge_cnt[i][j] > 0:
                ci = comp[i]
                cj = comp[j]
                if ci != cj:
                    m[ci][cj] += edge_cnt[i][j]

    # Compute out_m, in_m, div, isolated count
    out_m = [0]*K
    in_m = [0]*K
    for i in range(K):
        for j in range(K):
            if i != j:
                out_m[i] += m[i][j]
                in_m[i] += m[j][i]
    div = [out_m[i] - in_m[i] for i in range(K)]

    # Isolated components: no internal edges? Actually if out_m+in_m == 0 but there may be internal edges.
    # The definition: ins==0 and outs==0, i.e., no edges to/from other components.
    isolated = 0
    for i in range(K):
        if out_m[i] == 0 and in_m[i] == 0:
            isolated += 1

    # For components that have connections, we apply min-cut.
    # We'll only consider components with out_m+in_m > 0.
    # Build a list of component indices with connections.
    comps_with_edges = [i for i in range(K) if out_m[i] + in_m[i] > 0]
    M = len(comps_with_edges)
    if M == 0:
        # all isolated
        return isolated

    # Map old comp index to new index (0..M-1)
    idx_map = {old: new for new, old in enumerate(comps_with_edges)}

    S = M
    T = M + 1
    dinic = Dinic(M + 2)

    INF = 10**9
    total_pos = 0
    for old in comps_with_edges:
        i = idx_map[old]
        d = div[old]
        if d > 0:
            dinic.add_edge(S, i, d)
            total_pos += d
        elif d < 0:
            dinic.add_edge(i, T, -d)

    # Add reverse edges (j->i) for each condensation edge (i->j)
    for old_i in comps_with_edges:
        for old_j in comps_with_edges:
            if m[old_i][old_j] > 0:
                i = idx_map[old_i]
                j = idx_map[old_j]
                dinic.add_edge(j, i, INF)

    maxflow = dinic.max_flow(S, T)
    return total_pos - maxflow + isolated


